sp_widget.css:
.profile-card{

background:white;

border-radius:22px;

padding:36px;

box-shadow:
0 12px 40px rgba(0,0,0,.06);

height:100%;

}

.profile-card h2{

font-size:15px;

font-weight:700;

color:#12357D;

margin-bottom:30px;

}

.info-item{

background:#F4F7FD;

border-left:5px solid #4472D8;

border-radius:16px;

padding:18px 22px;

margin-bottom:18px;

display:flex;

flex-direction:column;

}

.info-item label{

font-size:15px;

font-weight:700;

color:#5B6785;

margin-bottom:8px;

}

.info-item span{

font-size:15px;

font-weight:700;

color:#163A82;

}

sp_widget.script:
(function() {

var sysId = $sp.getParameter('sys_id');

if (!sysId)
return;

var gr =
new GlideRecord(
'x_1902481_employ_0_employee'
);

if (gr.get(sysId)) {

data.employee_id =
gr.employee_id.toString();

data.department =
gr.department? gr.department.getDisplayValue(): '';

data.designation =
gr.designation? gr.designation.getDisplayValue(): '';
(function() {

data.employee_id = '';
data.department = '';
data.designation = '';
data.phone = '';
data.joining_date = '';

var sysId = $sp.getParameter('sys_id');

if (!sysId)
return;

var gr = new GlideRecord(
'x_1902481_employ_0_employee'
);

if (gr.get(sysId)) {

data.employee_id =
gr.employee_id? gr.employee_id.toString(): '-';

data.department =
gr.department? gr.department.getDisplayValue(): '-';

data.designation =
gr.designation? gr.designation.getDisplayValue(): '-';

data.phone =
gr.phone? gr.phone.toString(): '-';

/* FIXED FIELD */

data.joining_date =
gr.join_date? gr.join_date.getDisplayValue(): '-';

}

})();
data.phone =
gr.phone.toString();

data.join_date =
gr.join_date? gr.join_date.getDisplayValue(): '';

}

})();
